/**
 * Can this process ask a question on stderr? A strict superset of the
 * {@link isInteractive} gate cli-core's own prompts enforce (stdin TTY,
 * `TERM` not dumb, no `CI` — so its `NonInteractiveError` can never escape a
 * caller that checked here first), adding stderr-TTY because this package's
 * prompts render on stderr: a redirected stderr must refuse rather than block
 * on stdin with the question swallowed. It classifies whether definition
 * sharing can show its full first-run disclosure and guards interactive
 * prompts such as nuke's confirmation.
 */
export declare function canPromptOnStderr(): boolean;
/**
 * Ask a `select` question on stderr — the channel this package renders prompts
 * on so a redirected stdout can't swallow the question (the display side of the
 * {@link canPromptOnStderr} gate). The single site that routes a `select` to
 * stderr, so no `select` prompt can silently regress to stdout.
 */
export declare function selectOnStderr(config: {
    message: string;
    choices: readonly {
        name: string;
        value: string;
        description?: string;
    }[];
    /** The value the cursor starts on — e.g. an instance's current stage, so the
     *  picker opens where it already is. */
    default?: string;
}): Promise<string>;
/**
 * Ask a yes/no question on stderr, defaulting to NO — the {@link selectOnStderr}
 * sibling for a destructive confirmation. `default: false` both renders the
 * `[y/N]` hint and makes a bare Enter a decline, so proceeding always takes a
 * deliberate keystroke.
 */
export declare function confirmOnStderr(message: string): Promise<boolean>;
